parameters.query:
SELECT
  (SELECT row_to_json(x) FROM (SELECT id, codigo, nombre FROM espacios WHERE id::text = $1) x) AS espacio,
  (SELECT row_to_json(x) FROM (SELECT id, codigo, nombre FROM recursos WHERE id::text = $2) x) AS recurso;

