// =====================================================================
//  Reporte de una incidencia o solicitud: valida antes de registrarla
// =====================================================================
const LARGO_MINIMO_DESCRIPCION = 10;
const LARGO_MAXIMO_DESCRIPCION = 2000;

// ---------------------------------------------------------------------
//  Utilidades de validación
// ---------------------------------------------------------------------
const texto = (valor) => (valor === undefined || valor === null ? '' : String(valor).trim());
const numero = (valor) => (texto(valor) === '' ? NaN : Number(valor));
const esEnteroPositivo = (valor) => Number.isInteger(valor) && valor > 0;
const esFecha = (valor) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) return false;
  const fecha = new Date(`${valor}T00:00:00Z`);
  return !Number.isNaN(fecha.getTime()) && fecha.toISOString().slice(0, 10) === valor;
};
const esHora = (valor) => /^([01]\d|2[0-3]):[0-5]\d$/.test(valor);
const esFechaHora = (valor) => /^\d{4}-\d{2}-\d{2}T([01]\d|2[0-3]):[0-5]\d$/.test(valor) && esFecha(valor.slice(0, 10));
const aMinutos = (hora) => Number(hora.slice(0, 2)) * 60 + Number(hora.slice(3, 5));
// Suma días a "AAAA-MM-DDTHH:MM" (hora local del campus, sin zona horaria)
const sumarDias = (fechaHora, dias) => {
  const fecha = new Date(`${fechaHora}:00Z`);
  fecha.setUTCDate(fecha.getUTCDate() + dias);
  return fecha.toISOString().slice(0, 16);
};
const respuestaError = (status, code, message, details = []) => [
  { json: { ok: false, status, body: { ok: false, error: { code, message, details } } } },
];
const cuerpo = $('POST /incidencias').first().json.body ?? {};
const ctx = $input.first().json;

const descripcion = texto(cuerpo.descripcion);
const reportadoPor = texto(cuerpo.reportado_por);

const errores = [];
if (descripcion.length < LARGO_MINIMO_DESCRIPCION) {
  errores.push(`Describe la incidencia con al menos ${LARGO_MINIMO_DESCRIPCION} caracteres.`);
}
if (descripcion.length > LARGO_MAXIMO_DESCRIPCION) {
  errores.push(`La descripción admite máximo ${LARGO_MAXIMO_DESCRIPCION} caracteres.`);
}
if (!reportadoPor || reportadoPor.length > 120) errores.push('Indica quién reporta la incidencia.');
if (texto(cuerpo.espacio_id) && !ctx.espacio) errores.push('El espacio seleccionado no existe.');
if (texto(cuerpo.recurso_id) && !ctx.recurso) errores.push('El recurso seleccionado no existe.');
if (errores.length) {
  return respuestaError(422, 'DATOS_INVALIDOS', errores[0], errores.map((mensaje) => ({ regla: 'DATOS', mensaje })));
}

return [
  {
    json: {
      ok: true,
      descripcion,
      reportado_por: reportadoPor,
      espacio_id: ctx.espacio?.id ?? null,
      recurso_id: ctx.recurso?.id ?? null,
    },
  },
];

parameters.query:
INSERT INTO incidencias (descripcion, reportado_por, espacio_id, recurso_id, origen, motivo_estado, origen_estado)
VALUES ($1, $2, $3, $4, 'usuario', 'Reportada por ' || $2, 'usuario')
RETURNING id AS incidencia_id;

