// =====================================================================
//  Respuesta del reporte: la incidencia siempre queda registrada, aunque
//  el triaje con IA falle (en ese caso queda pendiente de triaje manual).
// =====================================================================
// Resume en una frase el resultado del triaje y sus efectos en otros módulos
const describirTriaje = (resultado) => {
  if (!resultado.clasificada) return `quedó pendiente de triaje manual (${resultado.error})`;
  const incidencia = resultado.incidencia;
  const quien = resultado.origen === 'manual' ? 'clasificada manualmente' : 'clasificada por la IA';
  const partes = [
    `${quien} como ${incidencia.categoria_nombre}, prioridad ${incidencia.prioridad}, asignada a ${incidencia.area_nombre}`,
  ];
  const efectos = resultado.efectos ?? {};
  partes.push(...(efectos.cambios ?? []));
  if (efectos.reservas_afectadas?.length) {
    partes.push(`${efectos.reservas_afectadas.length} reserva(s) futura(s) afectada(s): conviene reasignarlas`);
  }
  return partes.join('. ');
};
const incidenciaId = $('Registrar incidencia').first().json.incidencia_id;
const respuesta = $input.first().json;
const resultado =
  respuesta.encontrada === undefined
    ? { clasificada: false, error: respuesta.error ?? 'el triaje no se pudo ejecutar', incidencia: null }
    : respuesta;

return [
  {
    json: {
      status: 201,
      body: {
        ok: true,
        data: { incidencia_id: incidenciaId, ...resultado },
        message: `Incidencia #${incidenciaId} registrada y ${describirTriaje(resultado)}.`,
      },
    },
  },
];

// =====================================================================
//  Solicitud de (re)clasificación: con IA o manual
//  Solo se clasifican incidencias abiertas o en proceso.
// =====================================================================
const ESTADOS_CLASIFICABLES = ['abierta', 'en_proceso'];

// ---------------------------------------------------------------------
//  Utilidades de validación
// ---------------------------------------------------------------------
const texto = (valor) => (valor === undefined || valor === null ? '' : String(valor).trim());
const numero = (valor) => (texto(valor) === '' ? NaN : Number(valor));
const esEnteroPositivo = (valor) => Number.isInteger(valor) && valor > 0;
const esFecha = (valor) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) return false;
  const fecha = new Date(`${valor}T00:00:00Z`);
  return !Number.isNaN(fecha.getTime()) && fecha.toISOString().slice(0, 10) === valor;
};
const esHora = (valor) => /^([01]\d|2[0-3]):[0-5]\d$/.test(valor);
const esFechaHora = (valor) => /^\d{4}-\d{2}-\d{2}T([01]\d|2[0-3]):[0-5]\d$/.test(valor) && esFecha(valor.slice(0, 10));
const aMinutos = (hora) => Number(hora.slice(0, 2)) * 60 + Number(hora.slice(3, 5));
// Suma días a "AAAA-MM-DDTHH:MM" (hora local del campus, sin zona horaria)
const sumarDias = (fechaHora, dias) => {
  const fecha = new Date(`${fechaHora}:00Z`);
  fecha.setUTCDate(fecha.getUTCDate() + dias);
  return fecha.toISOString().slice(0, 16);
};
const respuestaError = (status, code, message, details = []) => [
  { json: { ok: false, status, body: { ok: false, error: { code, message, details } } } },
];
const cuerpo = $('POST /incidencias/triaje').first().json.body ?? {};
const incidencia = $input.first().json.incidencia;

if (!incidencia) return respuestaError(404, 'INCIDENCIA_NO_ENCONTRADA', 'La incidencia no existe.');
if (!ESTADOS_CLASIFICABLES.includes(incidencia.estado)) {
  return respuestaError(
    409,
    'INCIDENCIA_CERRADA',
    `La incidencia #${incidencia.id} está ${incidencia.estado}: solo se clasifican incidencias abiertas o en proceso.`,
  );
}

let manual = null;
if (cuerpo.manual) {
  manual = {
    categoria: texto(cuerpo.manual.categoria),
    prioridad: texto(cuerpo.manual.prioridad).toLowerCase(),
    area_responsable: texto(cuerpo.manual.area_responsable),
  };
  if (!manual.categoria || !manual.prioridad || !manual.area_responsable) {
    return respuestaError(422, 'CLASIFICACION_INCOMPLETA', 'La clasificación manual requiere categoría, prioridad y área.');
  }
}

return [{ json: { ok: true, incidencia_id: incidencia.id, manual } }];

// =====================================================================
//  Respuesta de la (re)clasificación
// =====================================================================
// Resume en una frase el resultado del triaje y sus efectos en otros módulos
const describirTriaje = (resultado) => {
  if (!resultado.clasificada) return `quedó pendiente de triaje manual (${resultado.error})`;
  const incidencia = resultado.incidencia;
  const quien = resultado.origen === 'manual' ? 'clasificada manualmente' : 'clasificada por la IA';
  const partes = [
    `${quien} como ${incidencia.categoria_nombre}, prioridad ${incidencia.prioridad}, asignada a ${incidencia.area_nombre}`,
  ];
  const efectos = resultado.efectos ?? {};
  partes.push(...(efectos.cambios ?? []));
  if (efectos.reservas_afectadas?.length) {
    partes.push(`${efectos.reservas_afectadas.length} reserva(s) futura(s) afectada(s): conviene reasignarlas`);
  }
  return partes.join('. ');
};
const resultado = $input.first().json;
const error = (status, code, message) => [{ json: { status, body: { ok: false, error: { code, message, details: [] } } } }];

if (resultado.encontrada === undefined) {
  return error(500, 'TRIAJE_FALLIDO', `El triaje no se pudo ejecutar: ${resultado.error ?? 'error desconocido'}`);
}
if (!resultado.encontrada) return error(404, 'INCIDENCIA_NO_ENCONTRADA', 'La incidencia no existe.');
if (!resultado.clasificada) {
  return resultado.origen === 'manual'
    ? error(422, 'CLASIFICACION_INVALIDA', resultado.error)
    : error(502, 'IA_NO_DISPONIBLE', `La IA no pudo clasificar la incidencia: ${resultado.error}`);
}

return [
  {
    json: {
      status: 200,
      body: { ok: true, data: resultado, message: `Incidencia #${resultado.incidencia.id} ${describirTriaje(resultado)}.` },
    },
  },
];

// =====================================================================
//  CICLO DE VIDA DE UNA INCIDENCIA (RN-12)
//  Solo se permiten estas transiciones. Al resolver o cerrar se exige un
//  comentario; después se recalculan los bloqueos (RN-10 / RN-11).
// =====================================================================
const TRANSICIONES = {
  abierta: ['en_proceso', 'resuelta', 'cerrada'],
  en_proceso: ['abierta', 'resuelta'],
  resuelta: ['cerrada', 'abierta'],
  cerrada: [],
};
const ESTADOS_QUE_EXIGEN_COMENTARIO = ['resuelta', 'cerrada'];
const LARGO_MINIMO_COMENTARIO = 5;

// ---------------------------------------------------------------------
//  Utilidades de validación
// ---------------------------------------------------------------------
const texto = (valor) => (valor === undefined || valor === null ? '' : String(valor).trim());
const numero = (valor) => (texto(valor) === '' ? NaN : Number(valor));
const esEnteroPositivo = (valor) => Number.isInteger(valor) && valor > 0;
const esFecha = (valor) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) return false;
  const fecha = new Date(`${valor}T00:00:00Z`);
  return !Number.isNaN(fecha.getTime()) && fecha.toISOString().slice(0, 10) === valor;
};
const esHora = (valor) => /^([01]\d|2[0-3]):[0-5]\d$/.test(valor);
const esFechaHora = (valor) => /^\d{4}-\d{2}-\d{2}T([01]\d|2[0-3]):[0-5]\d$/.test(valor) && esFecha(valor.slice(0, 10));
const aMinutos = (hora) => Number(hora.slice(0, 2)) * 60 + Number(hora.slice(3, 5));
// Suma días a "AAAA-MM-DDTHH:MM" (hora local del campus, sin zona horaria)
const sumarDias = (fechaHora, dias) => {
  const fecha = new Date(`${fechaHora}:00Z`);
  fecha.setUTCDate(fecha.getUTCDate() + dias);
  return fecha.toISOString().slice(0, 16);
};
const respuestaError = (status, code, message, details = []) => [
  { json: { ok: false, status, body: { ok: false, error: { code, message, details } } } },
];
const cuerpo = $('PATCH /incidencias/estado').first().json.body ?? {};
const incidencia = $input.first().json.incidencia;
const estado = texto(cuerpo.estado).toLowerCase();
const comentario = texto(cuerpo.comentario).slice(0, 500);

if (!incidencia) return respuestaError(404, 'INCIDENCIA_NO_ENCONTRADA', 'La incidencia no existe.');
if (!(estado in TRANSICIONES)) {
  return respuestaError(422, 'ESTADO_INVALIDO', `Estado no válido. Usa uno de: ${Object.keys(TRANSICIONES).join(', ')}.`);
}
const permitidos = TRANSICIONES[incidencia.estado] ?? [];
if (!permitidos.includes(estado)) {
  const opciones = permitidos.length ? `solo se permite pasar a: ${permitidos.join(', ')}` : 'es un estado final';
  return respuestaError(
    409,
    'TRANSICION_INVALIDA',
    `La incidencia #${incidencia.id} no puede pasar de "${incidencia.estado}" a "${estado}": desde "${incidencia.estado}" ${opciones}.`,
    [{ regla: 'RN-12', mensaje: `Transición ${incidencia.estado} → ${estado} no permitida` }],
  );
}
if (ESTADOS_QUE_EXIGEN_COMENTARIO.includes(estado) && comentario.length < LARGO_MINIMO_COMENTARIO) {
  return respuestaError(422, 'COMENTARIO_REQUERIDO', `Para marcarla como "${estado}" describe cómo se solucionó.`);
}

return [{ json: { ok: true, id: incidencia.id, estado, comentario: comentario || `Cambio a ${estado}` } }];

// =====================================================================
//  Respuesta del cambio de estado (incluye rehabilitaciones por RN-11)
// =====================================================================
const resultado = $input.first().json;
const id = $('Cambiar estado de la incidencia').first().json.incidencia_id;

if (!resultado.incidencia) {
  return [
    {
      json: {
        status: 500,
        body: {
          ok: false,
          error: {
            code: 'EFECTOS_FALLIDOS',
            message: `El estado de la incidencia #${id} cambió, pero no se pudieron recalcular los bloqueos: ${resultado.error ?? 'error desconocido'}`,
            details: [],
          },
        },
      },
    },
  ];
}

const partes = [`Incidencia #${id} ahora está "${resultado.incidencia.estado}".`, ...resultado.cambios.map((c) => `${c}.`)];
return [{ json: { status: 200, body: { ok: true, data: resultado, message: partes.join(' ') } } }];

// =====================================================================
//  Traduce los errores de PostgreSQL a respuestas claras.
//  Las restricciones de la base de datos son la última barrera de
//  integridad: si dos peticiones simultáneas se saltan una regla, la base
//  de datos rechaza la segunda y aquí se explica el motivo al usuario.
// =====================================================================
const RESTRICCIONES = {
  reservas_sin_solapamiento: [409, 'CONFLICTO_HORARIO', 'El espacio ya tiene una reserva activa que se cruza con ese horario.'],
  espacios_codigo_unico: [409, 'CODIGO_DUPLICADO', 'Ya existe un espacio con ese código.'],
  recursos_codigo_unico: [409, 'CODIGO_DUPLICADO', 'Ya existe un recurso con ese código.'],
  prestamos_un_activo_por_recurso: [409, 'RECURSO_YA_PRESTADO', 'El recurso ya tiene un préstamo activo.'],
  recursos_espacio_id_fkey: [422, 'ESPACIO_INEXISTENTE', 'El espacio indicado no existe.'],
  espacios_capacidad_positiva: [422, 'CAPACIDAD_INVALIDA', 'La capacidad debe ser mayor que cero.'],
  reservas_rango_horario: [422, 'HORARIO_INVALIDO', 'La hora de fin debe ser posterior a la de inicio.'],
  prestamos_limite_posterior: [422, 'FECHA_INVALIDA', 'La fecha límite debe ser posterior a la fecha del préstamo.'],
  incidencias_clasificacion_completa: [422, 'CLASIFICACION_INCOMPLETA', 'La clasificación requiere categoría, prioridad y área.'],
};

const fallo = $input.first().json;
const detalle = `${fallo.message ?? ''} ${fallo.error?.description ?? ''}`;

const restriccion = Object.keys(RESTRICCIONES).find((nombre) => detalle.includes(nombre));
if (restriccion) {
  const [status, code, message] = RESTRICCIONES[restriccion];
  return [{ json: { status, body: { ok: false, error: { code, message, details: [{ regla: 'BD', mensaje: restriccion }] } } } }];
}

const sinConexion = /Connection refused|ECONNREFUSED|Host not found|ENOTFOUND|timed out/i.test(detalle);
return [
  {
    json: {
      status: sinConexion ? 503 : 500,
      body: {
        ok: false,
        error: {
          code: sinConexion ? 'BD_NO_DISPONIBLE' : 'ERROR_BASE_DE_DATOS',
          message: sinConexion
            ? 'La base de datos no está disponible en este momento.'
            : 'No fue posible completar la operación en la base de datos.',
          details: [{ regla: 'BD', mensaje: String(fallo.message ?? '').slice(0, 300) }],
        },
      },
    },
  },
];
